import{_ as t,o as s,c as a,l as o,t as n,N as r}from"./chunks/framework.Gjrf2Eoj.js";const b=JSON.parse('{"title":"df | x-cmd man (man1) | report file system space usage","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | df - report file system space usage","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"df | x-cmd man (man1) | report file system space usage"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | df - report file system space usage"}]]},"headers":[],"params":{"isMan":true,"man":"df","category":"man1","desc":"report file system space usage"},"relativePath":"man1/df.md","filePath":"man1/df.md"}'),i={name:"man1/df.md"},d={class:"visually-hidden"},l=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>df - report file system space usage</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>df</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>This manual page documents the GNU version of <strong>df</strong>. <strong>df</strong> displays the amount of space available on the file system containing each file name argument. If no file name is given, the space available on all currently mounted file systems is shown. Space is shown in 1K blocks by default, unless the environment variable POSIXLY_CORRECT is set, in which case 512-byte blocks are used.</p><p>If an argument is the absolute file name of a device node containing a mounted file system, <strong>df</strong> shows the space available on that file system rather than on the file system containing the device node. This version of <strong>df</strong> cannot show the space available on unmounted file systems, because on most kinds of systems doing so requires non-portable intimate knowledge of file system structures.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>Show information about the file system on which each FILE resides, or all file systems by default.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-a</strong>, <strong>--all</strong></dt><dd>include pseudo, duplicate, inaccessible file systems</dd><dt><strong>-B</strong>, <strong>--block-size</strong>=<em>SIZE</em></dt><dd>scale sizes by SIZE before printing them; e.g., &#39;-BM&#39; prints sizes in units of 1,048,576 bytes; see SIZE format below</dd><dt><strong>-h</strong>, <strong>--human-readable</strong></dt><dd>print sizes in powers of 1024 (e.g., 1023M)</dd><dt><strong>-H</strong>, <strong>--si</strong></dt><dd>print sizes in powers of 1000 (e.g., 1.1G)</dd><dt><strong>-i</strong>, <strong>--inodes</strong></dt><dd>list inode information instead of block usage</dd><dt><strong>-k</strong></dt><dd>like <strong>--block-size</strong>=<em>1K</em></dd><dt><strong>-l</strong>, <strong>--local</strong></dt><dd>limit listing to local file systems</dd><dt><strong>--no-sync</strong></dt><dd>do not invoke sync before getting usage info (default)</dd><dt><strong>--output</strong>[=<em>FIELD_LIST</em>]</dt><dd>use the output format defined by FIELD_LIST, or print all fields if FIELD_LIST is omitted.</dd><dt><strong>-P</strong>, <strong>--portability</strong></dt><dd>use the POSIX output format</dd><dt><strong>--sync</strong></dt><dd>invoke sync before getting usage info</dd><dt><strong>--total</strong></dt><dd>elide all entries insignificant to available space, and produce a grand total</dd><dt><strong>-t</strong>, <strong>--type</strong>=<em>TYPE</em></dt><dd>limit listing to file systems of type TYPE</dd><dt><strong>-T</strong>, <strong>--print-type</strong></dt><dd>print file system type</dd><dt><strong>-x</strong>, <strong>--exclude-type</strong>=<em>TYPE</em></dt><dd>limit listing to file systems not of type TYPE</dd><dt><strong>-v</strong></dt><dd>(ignored)</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>Display values are in units of the first available SIZE from <strong>--block-size</strong>, and the DF_BLOCK_SIZE, BLOCK_SIZE and BLOCKSIZE environment variables. Otherwise, units default to 1024 bytes (or 512 if POSIXLY_CORRECT is set).</p><p>The SIZE argument is an integer and optional unit (example: 10K is 10*1024). Units are K,M,G,T,P,E,Z,Y,R,Q (powers of 1024) or KB,MB,... (powers of 1000). Binary prefixes can be used, too: KiB=K, MiB=M, and so on.</p><p>FIELD_LIST is a comma-separated list of columns to be included. Valid field names are: &#39;source&#39;, &#39;fstype&#39;, &#39;itotal&#39;, &#39;iused&#39;, &#39;iavail&#39;, &#39;ipcent&#39;, &#39;size&#39;, &#39;used&#39;, &#39;avail&#39;, &#39;pcent&#39;, &#39;file&#39; and &#39;target&#39; (see info page).</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Torbjorn Granlund, David MacKenzie, and Paul Eggert.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/df%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/df\\</a>&gt; <br> or available locally via: info &#39;(coreutils) df invocation&#39;</p>',22);function g(e,p,m,f,c,h){return s(),a("div",null,[o("h1",d,n(e.$params.man),1),l])}const y=t(i,[["render",g]]);export{b as __pageData,y as default};
